const input = $json;

if (!input.body?.data?.messageTimestamp) {
  throw new Error("No se encontró messageTimestamp en el input");
}

const timestamp = input.body.data.messageTimestamp;

// Siempre UTC
const dateUTC = new Date(timestamp * 1000);
const isoString = dateUTC.toISOString(); // ISO válido para n8n

const output = {
  ...input,
  body: {
    ...input.body,
    date_time: isoString
  }
};

return { json: output };

// Tomamos la respuesta de la IA
const raw = $input.first().json.response;

// Limpiamos ```json, ``` y saltos de línea innecesarios
const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();

// Convertimos a JSON real
const parsed = JSON.parse(cleaned);

// Retornamos como objeto JSON usable por n8n
return [{ json: parsed }];

// === Leer los datos de entrada ===
const input = $input.first().json;

// === Función auxiliar ===
function toArray(value, splitByNewline = true) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(v => String(v).trim()).filter(Boolean);
  if (typeof value === "string") {
    return splitByNewline
      ? value.split(/\n+/).map(v => v.trim()).filter(Boolean)
      : [value.trim()];
  }
  return [String(value)];
}

// === Recuperar conversación anterior (si existe) ===
let conversacionAnterior = "";
if (input.conversacion_anterior) {
  conversacionAnterior = Array.isArray(input.conversacion_anterior)
    ? input.conversacion_anterior.join("\n")
    : String(input.conversacion_anterior).trim();
}

// === Normalizar entradas ===
let mensajes = toArray(input.Nuevos_mensajes);
const respuestas = toArray(input.respuesta_al_usuario, false);
const fotos = toArray(input.fotos);
const audios = toArray(input.audio);
const piesDeFoto = toArray(input.pie_de_foto, true);

// === Construir bloque de mensajes ===
if (mensajes.length === 0) {
  // No hay mensajes → usar fotos + audios
  mensajes = [...fotos, ...audios].filter(Boolean);
} else {
  // Hay mensajes → agregar fotos y audios al final si existen
  if (fotos.length > 0) {
    fotos.forEach((f, i) => {
      const pie = piesDeFoto[i] ? `\nPie de foto: ${piesDeFoto[i]}` : "";
      mensajes.push(`📸 Foto: ${f}${pie}`);
    });
  }
  if (audios.length > 0) {
    audios.forEach(a => mensajes.push(`🎧 Audio: ${a}`));
  }
}

// === Numerar ===
function numerar(lista, prefijo) {
  return lista.map((msg, i) => {
    const regex = new RegExp(`^${prefijo}\\s*#?\\d*:`, "i");
    return regex.test(msg) ? msg : `${prefijo} #${i + 1}: ${msg}`;
  });
}

const mensajesNumerados = numerar(mensajes, "Mensaje");
const respuestasNumeradas = numerar(respuestas, "Respuesta");

// === Crear nuevo bloque con la acción al final ===
let nuevoBloque = `${mensajesNumerados.join("\n")}\n${respuestasNumeradas.join("\n")}`.trim();

// Añadir la acción al final del último bloque
if (input.action) {
  nuevoBloque += `\n[Accion anterior: ${input.action}]`;
}

// === Combinar con conversación previa ===
const conversacionFinal = conversacionAnterior
  ? `${conversacionAnterior}\n${nuevoBloque}`.trim()
  : nuevoBloque;

// === Crear objeto para Redis ===
const objetoRedis = { conversacion_anterior: conversacionFinal };
const stringParaRedis = JSON.stringify(objetoRedis);

// === Devolver todo ===
return [
  {
    json: {
      ...input,
      conversacion_anterior: conversacionFinal,
      stringParaRedis
    }
  }
];

