// Combinar todos los objetos en uno solo
// Si hay claves duplicadas, las del input más a la derecha sobrescriben a las anteriores
const combinado = Object.assign({}, ...entradas);

// Devolver el objeto final combinado
return [
  {
    json: combinado
  }
